from claude_agent_sdk import query, ClaudeAgentOptions, HookMatcher

async def guard(input_data, tool_use_id, ctx):
    cmd = input_data["tool_input"].get("command", "")
    if "rm -rf" in cmd:
        return {"hookSpecificOutput": {"hookEventName": "PreToolUse",
                "permissionDecision": "deny",
                "permissionDecisionReason": "Destructive command blocked"}}
    return {}

opts = ClaudeAgentOptions(
    allowed_tools=["Read", "Grep", "Glob"], permission_mode="dontAsk",
    hooks={"PreToolUse": [HookMatcher(matcher="Bash", hooks=[guard])]},
    max_turns=30, max_budget_usd=5.0)
# async for msg in query(prompt="Find the auth bug", options=opts): ...

let msg = await client.messages.create({ model, max_tokens: 16000, tools, messages });
for (let i = 0; msg.stop_reason === "tool_use" && i < 25; i++) {
  messages.push({ role: "assistant", content: msg.content }); // full content
  const results = await Promise.all(
    msg.content.filter((b) => b.type === "tool_use").map(async (b) => {
      try { return { type: "tool_result", tool_use_id: b.id, content: await run(b) }; }
      catch (e) { return { type: "tool_result", tool_use_id: b.id, is_error: true, content: String(e) }; }
    }));
  messages.push({ role: "user", content: results }); // one message, all results
  msg = await client.messages.create({ model, max_tokens: 16000, tools, messages });
}
if (msg.stop_reason === "max_tokens") throw new Error("Truncated");

const protectEnv: HookCallback = async (input) => {
  const p = (input as PreToolUseHookInput).tool_input as any;
  if (p.file_path?.endsWith(".env")) {
    return { hookSpecificOutput: { hookEventName: "PreToolUse",
      permissionDecision: "deny", permissionDecisionReason: "No .env" } };
  }
  return {};
};
const options = { hooks: { PreToolUse: [{ matcher: "Write|Edit", hooks: [protectEnv] }] } };

for await (const m of query({ prompt, options: { maxTurns: 8 } })) {
  if (m.type === "result") {
    await saveReport(m.result);   // sometimes undefined
  }
}

def handle(req):
    agent = client.beta.agents.create(
        name="triage", model=MODEL, system=SYSTEM, tools=TOOLS)
    session = client.beta.sessions.create(
        agent=agent.id, environment_id=ENV_ID)
    return run(session, req.text)

for (const block of msg.content) {
  if (block.type !== "tool_use") continue;
  const out = await runTool(block);
  messages.push({ role: "user", content: [
    { type: "tool_result", tool_use_id: block.id, content: out },
  ]});
}

while (true) {
  const msg = await client.messages.create({ model, max_tokens: 1024, tools, messages });
  if (msg.stop_reason !== "tool_use") return finalText(msg);
  messages.push({ role: "assistant", content: msg.content });
  messages.push({ role: "user", content: await runTools(msg) });
}
